import { useState } from "react";

// Shows a delivery failure with how many times the webhook was retried.
export function RetryToast(props: { readonly attempts: number; readonly onClose: () => void }) {
  return (
    <div className="toast" style={{ position: "relative", width: 320 }}>
      <span>Delivery failed</span>
      <span className="count" style={{ position: "absolute", right: 0, top: 0 }}>
        Retried {props.attempts}x
      </span>
      <button type="button" className="close" style={{ position: "absolute", right: 0, top: 0 }} onClick={props.onClose}>
        Close
      </button>
    </div>
  );
}
